export interface RequestOptions {
  timeout?: number;
  retries?: number;
  headers?: Record<string, string>;
  json?: boolean;
  /** @deprecated Use `timeout` instead. */
  maxWait?: number;
}

export interface ClientOptions {
  timeout?: number;
  retries?: number;
  keepAlive?: boolean;
  auth?: { user: string; pass: string };
}

export interface Response {
  status: number;
  body: string;
}

export interface Client {
  get(url: string, options?: RequestOptions): Promise<Response>;
  post(url: string, body?: unknown, options?: RequestOptions): Promise<Response>;
}

export function createClient(baseUrl: string, options?: ClientOptions): Client;
export function get(url: string, options?: RequestOptions): Promise<Response>;
export function post(url: string, body?: unknown, options?: RequestOptions): Promise<Response>;

/** @deprecated Use `get` instead; fetchUrl ignores redirects. */
export function fetchUrl(url: string): Promise<Response>;
